#include "drv_i2c_mpu6050.h"
#include <avr/io.h>

typedef enum {
    I2C_IDLE,
    I2C_START,
    I2C_SLA_W,
    I2C_REG_ADDR,
    I2C_DATA_W,
    I2C_REP_START,
    I2C_SLA_R,
    I2C_DATA_R
} i2c_state_t;

static uint8_t i2c_target_reg;
static uint8_t i2c_data;
static uint8_t i2c_is_read;
static uint8_t i2c_busy;
static uint8_t i2c_error;
static i2c_state_t i2c_state;

static drv_mpu6050_state_t mpu_state = DRV_MPU6050_STATE_UNINIT;
static uint32_t mpu_wait_start_ms = 0;

static void i2c_error_stop(void) {
    i2c_error = 1;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 7) | (1 << 4) | (1 << 2);
    i2c_busy = 0;
    i2c_state = I2C_IDLE;
}

static void i2c_start_write(uint8_t reg, uint8_t data) {
    i2c_target_reg = reg;
    i2c_data = data;
    i2c_is_read = 0;
    i2c_busy = 1;
    i2c_error = 0;
    i2c_state = I2C_START;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 7) | (1 << 5) | (1 << 2);
}

static void i2c_start_read(uint8_t reg) {
    i2c_target_reg = reg;
    i2c_is_read = 1;
    i2c_busy = 1;
    i2c_error = 0;
    i2c_state = I2C_START;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 7) | (1 << 5) | (1 << 2);
}

static void i2c_task(void) {
    if (!i2c_busy) return;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    if (!(TWCR & (1 << 7))) return;

    // ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232
    uint8_t status = TWSR & 0xF8;

    switch (i2c_state) {
        case I2C_START:
            if (status == 0x08 || status == 0x10) {
                TWDR = 0x68 << 1;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << 7) | (1 << 2);
                i2c_state = I2C_SLA_W;
            } else {
                i2c_error_stop();
            }
            break;
        case I2C_SLA_W:
            if (status == 0x18) {
                TWDR = i2c_target_reg;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << 7) | (1 << 2);
                i2c_state = I2C_REG_ADDR;
            } else {
                i2c_error_stop();
            }
            break;
        case I2C_REG_ADDR:
            if (status == 0x28) {
                if (i2c_is_read) {
                    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                    TWCR = (1 << 7) | (1 << 5) | (1 << 2);
                    i2c_state = I2C_REP_START;
                } else {
                    TWDR = i2c_data;
                    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                    TWCR = (1 << 7) | (1 << 2);
                    i2c_state = I2C_DATA_W;
                }
            } else {
                i2c_error_stop();
            }
            break;
        case I2C_DATA_W:
            if (status == 0x28) {
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << 7) | (1 << 4) | (1 << 2);
                i2c_busy = 0;
                i2c_state = I2C_IDLE;
            } else {
                i2c_error_stop();
            }
            break;
        case I2C_REP_START:
            if (status == 0x10) {
                TWDR = (0x68 << 1) | 1;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << 7) | (1 << 2);
                i2c_state = I2C_SLA_R;
            } else {
                i2c_error_stop();
            }
            break;
        case I2C_SLA_R:
            if (status == 0x40) {
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << 7) | (1 << 2);
                i2c_state = I2C_DATA_R;
            } else {
                i2c_error_stop();
            }
            break;
        case I2C_DATA_R:
            if (status == 0x58) {
                i2c_data = TWDR;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << 7) | (1 << 4) | (1 << 2);
                i2c_busy = 0;
                i2c_state = I2C_IDLE;
            } else {
                i2c_error_stop();
            }
            break;
        default:
            i2c_error_stop();
            break;
    }
}

void drv_i2c_mpu6050_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR &= ~((1 << 1) | (1 << 0));
    TWBR = 12;
    TWCR = (1 << 2);

    mpu_state = DRV_MPU6050_STATE_INIT_START;
    i2c_state = I2C_IDLE;
    i2c_busy = 0;
    i2c_error = 0;
}

void drv_i2c_mpu6050_task(uint32_t sys_time_ms) {
    i2c_task();

    if (i2c_busy) return;

    if (i2c_error && mpu_state != DRV_MPU6050_STATE_ERROR) {
        mpu_state = DRV_MPU6050_STATE_ERROR;
        return;
    }

    switch (mpu_state) {
        case DRV_MPU6050_STATE_INIT_START:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_start_read(0x75);
            mpu_state = DRV_MPU6050_STATE_INIT_READ_WHOAMI;
            break;
        case DRV_MPU6050_STATE_INIT_READ_WHOAMI:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            if (i2c_data == 0x68) {
                i2c_start_write(0x6B, 0x80);
                mpu_state = DRV_MPU6050_STATE_INIT_RESET;
            } else {
                mpu_state = DRV_MPU6050_STATE_ERROR;
            }
            break;
        case DRV_MPU6050_STATE_INIT_RESET:
            mpu_wait_start_ms = sys_time_ms;
            mpu_state = DRV_MPU6050_STATE_INIT_WAIT_RESET;
            break;
        case DRV_MPU6050_STATE_INIT_WAIT_RESET:
            if (sys_time_ms - mpu_wait_start_ms >= 100) {
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_start_write(0x6B, 0x01);
                mpu_state = DRV_MPU6050_STATE_INIT_WAKEUP;
            }
            break;
        case DRV_MPU6050_STATE_INIT_WAKEUP:
            mpu_wait_start_ms = sys_time_ms;
            mpu_state = DRV_MPU6050_STATE_INIT_WAIT_WAKEUP;
            break;
        case DRV_MPU6050_STATE_INIT_WAIT_WAKEUP:
            if (sys_time_ms - mpu_wait_start_ms >= 100) {
                // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                i2c_start_write(0x1A, 0x03);
                mpu_state = DRV_MPU6050_STATE_INIT_CONFIG;
            }
            break;
        case DRV_MPU6050_STATE_INIT_CONFIG:
            mpu_state = DRV_MPU6050_STATE_READY;
            break;
        case DRV_MPU6050_STATE_READY:
        case DRV_MPU6050_STATE_ERROR:
        case DRV_MPU6050_STATE_UNINIT:
        default:
            break;
    }
}

void drv_i2c_mpu6050_write_reg_async(uint8_t reg, uint8_t data) {
    if (mpu_state != DRV_MPU6050_STATE_READY || i2c_busy) return;
    i2c_start_write(reg, data);
}

void drv_i2c_mpu6050_read_reg_async(uint8_t reg) {
    if (mpu_state != DRV_MPU6050_STATE_READY || i2c_busy) return;
    i2c_start_read(reg);
}

uint8_t drv_i2c_mpu6050_is_busy(void) {
    return i2c_busy;
}

uint8_t drv_i2c_mpu6050_get_data(void) {
    return i2c_data;
}

drv_mpu6050_state_t drv_i2c_mpu6050_get_state(void) {
    return mpu_state;
}
