```file:src/pid_controller.c
#include "pid_controller.h"

/* THIẾU THÔNG TIN: Không có trích đoạn tài liệu nào được cung cấp. 
   Không có hàm cấu hình thanh ghi phần cứng nào được cài đặt để tránh vi phạm ràng buộc. */

void pid_controller_init(pid_ctrl_t *pid, int32_t kp, int32_t ki, int32_t kd, int32_t out_min, int32_t out_max) {
    if (!pid) {
        return;
    }

    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->out_min = out_min;
    pid->out_max = out_max;
    pid->integral = 0;
    pid->prev_error = 0;

    if (ki != 0) {
        pid->integral_max = out_max / ki;
        pid->integral_min = out_min / ki;
    } else {
        pid->integral_max = 0;
        pid->integral_min = 0;
    }
}

void pid_controller_reset(pid_ctrl_t *pid) {
    if (!pid) {
        return;
    }
    pid->integral = 0;
    pid->prev_error = 0;
}

int32_t pid_controller_update(pid_ctrl_t *pid, int32_t setpoint, int32_t measured, int32_t dt_ms) {
    if (!pid || dt_ms <= 0) {
        return 0;
    }

    int32_t error = setpoint - measured;

    int32_t p_term = pid->kp * error;

    pid->integral += (error * dt_ms);

    if (pid->ki != 0) {
        if (pid->integral > pid->integral_max) {
            pid->integral = pid->integral_max;
        } else if (pid->integral < pid->integral_min) {
            pid->integral = pid->integral_min;
        }
    }

    int32_t i_term = pid->ki * pid->integral;

    int32_t derivative = (error - pid->prev_error) / dt_ms;
    int32_t d_term = pid->kd * derivative;

    pid->prev_error = error;

    int32_t output = p_term + i_term + d_term;

    if (output > pid->out_max) {
        output = pid->out_max;
    } else if (output < pid->out_min) {
        output = pid->out_min;
    }

    return output;
}
